<?php
$b64 = "";

$zipContent = base64_decode($b64);
file_put_contents('debug.zip', $zipContent);

$zip = new ZipArchive;
$res = $zip->open('debug.zip');

if ($res === TRUE) {
    if ($zip->locateName('xml.xml') !== false) {
        $xml = $zip->getFromName('xml.xml');
        echo "XML Length: " . strlen($xml) . "\n";
        
        $dom = new DOMDocument;
        $dom->preserveWhiteSpace = false;
        $dom->formatOutput = true;
        @$dom->loadXML($xml);
        echo "Root Node: " . $dom->documentElement->nodeName . "\n";
        
        $signatures = $dom->getElementsByTagName('Signature');
        echo "Number of Signatures: " . $signatures->length . "\n";
        
        if ($signatures->length > 0) {
            echo "Signature found.\n";
            echo $dom->saveXML($signatures->item(0));
        } else {
            echo "NO SIGNATURE FOUND IN XML.\n";
            echo substr($xml, 0, 1000) . "...\n"; // Preview start
        }
    } else {
        echo "xml.xml not found in zip.\n";
    }
    $zip->close();
} else {
    echo "Failed to open zip.\n";
}
unlink('debug.zip');
?>
